import time, os, random, hashlib
from cryptography.hazmat.primitives import hashes

def hash_crypto(data):
    h = hashes.Hash(hashes.SHA256())
    h.update(data)
    return h.finalize()

def hash_hashlib(data):
    return hashlib.sha256(data).digest()

