import time, random, hashlib
from cryptography.hazmat.primitives import hashes

def timeit(fn, *args):
    t0=time.perf_counter(); fn(*args); return time.perf_counter()-t0

sizes=[20480000]
for s in sizes:
    data=random.randbytes(s)
    def crypto():
        h=hashes.Hash(hashes.SHA256()); h.update(data); h.finalize()
    def hl():
        hashlib.sha256(data).digest()
    tcrypto=min(timeit(crypto) for _ in range(3))
    thl=min(timeit(hl) for _ in range(3))
    print('size', s, tcrypto, thl, 'ratio', tcrypto/thl)
